ENR[9] = {
 "Pourquoi existe-t-il des entreprises ? Les coûts de transaction": {
  'af': "Coase part d'une énigme que la théorie standard ne pose pas : si le marché est le mode d'allocation le plus efficace, pourquoi existe-t-il des entreprises, c'est-à-dire des îlots où l'allocation se fait par l'ordre et non par le prix ? Sa réponse est que le recours au marché a un coût, et que l'entreprise existe précisément parce qu'elle permet de l'éviter. Passer par le marché suppose en effet de chercher un fournisseur, de comparer les offres, de négocier un prix, de rédiger un contrat, d'en surveiller l'exécution et de régler les litiges : ce sont les coûts de transaction. Organiser la même activité en interne les supprime mais en crée d'autres, les coûts d'organisation, qui croissent avec la taille — perte d'information dans la hiérarchie, lenteur, erreurs d'allocation. La firme s'étend donc jusqu'au point où le coût d'une transaction supplémentaire organisée en interne égale celui de la même transaction sur le marché.",
  'po': "Dans le chapitre, cette thèse fonde l'ensemble des théories de la firme : elle répond simultanément à trois questions — pourquoi des firmes existent, pourquoi elles ne sont pas infinies, pourquoi le marché ne disparaît pas — et donne un critère pour déterminer la frontière de l'entreprise. Toutes les approches examinées ensuite se définissent par rapport à elle.",
  'co': "Ronald Coase explique l'existence de la firme par les coûts de transaction : le recours au marché suppose de chercher, négocier, contracter et surveiller, et l'entreprise s'étend jusqu'au point où le coût d'organiser en interne égale celui de passer par le marché.",
 },
 "Approche transactionnelle : spécificité des actifs et opportunisme": {
  'af': "Williamson soutient que le choix entre le marché, le contrat de long terme et l'intégration ne dépend pas de l'activité en général mais des caractéristiques de chaque transaction, et il identifie les deux hypothèses comportementales qui rendent ce choix nécessaire : la rationalité limitée et l'opportunisme. La rationalité limitée implique que les contrats soient nécessairement incomplets, puisqu'on ne peut prévoir toutes les circonstances futures. L'opportunisme implique que cette incomplétude sera exploitée dès qu'il deviendra profitable de le faire. Le facteur décisif est alors la spécificité des actifs : lorsqu'un investissement n'a de valeur que dans une relation déterminée, celui qui l'a engagé devient captif et s'expose au hold-up, c'est-à-dire à une renégociation à son détriment. Plus la spécificité, l'incertitude et la fréquence des transactions sont élevées, plus le marché devient coûteux et plus l'intégration verticale s'impose comme structure de gouvernance appropriée.",
  'po': "Dans le chapitre, cette analyse opérationnalise l'intuition de Coase en fournissant les variables qui déterminent la frontière de la firme, ce qui la rend directement applicable aux décisions d'externalisation. Elle constitue l'un des deux termes de la grande opposition du chapitre, face à l'approche contractuelle d'Alchian et Demsetz.",
  'co': "Oliver Williamson montre que la spécificité des actifs commande le choix entre marché et hiérarchie : un investissement qui n'a de valeur que dans une relation donnée expose son auteur au hold-up, de sorte que l'intégration verticale devient la structure de gouvernance la moins coûteuse.",
 },
 "La firme comme nœud de contrats et le travail en équipe": {
  'af': "Alchian soutient que la firme n'est pas d'une autre nature que le marché mais un ensemble de contrats librement consentis, et que si une hiérarchie y apparaît, c'est en raison d'un problème de mesure et non d'un pouvoir de commandement. La thèse part du travail en équipe : lorsque la production est le fruit d'un effort collectif, le résultat est commun et indivisible, de sorte qu'on ne peut pas isoler la contribution de chacun. Chaque membre est alors incité à réduire son effort, puisque le coût de son relâchement est supporté par l'équipe entière. La solution consiste à confier à un agent spécialisé la surveillance des autres ; mais il faut alors inciter le surveillant lui-même, ce qui se fait en lui attribuant le revenu résiduel, c'est-à-dire ce qui reste une fois les autres apporteurs rémunérés. L'autorité patronale n'est donc pas un droit de commander mais la conséquence d'une difficulté de mesure.",
  'po': "Dans le chapitre, cette thèse constitue l'alternative radicale à l'approche transactionnelle : si la firme n'est qu'un faisceau de contrats, la distinction entre firme et marché s'efface, et le pouvoir hiérarchique perd toute spécificité. L'opposition entre ces deux lectures structure la partie consacrée aux théories de la firme.",
  'co': "Pour Alchian et Demsetz, la firme est un nœud de contrats et non une alternative au marché : c'est l'impossibilité de mesurer la contribution individuelle dans le travail en équipe qui justifie la surveillance, le surveillant étant incité par l'attribution du revenu résiduel.",
 },
 "Mesure de l'apport et justification du contrôle": {
  'af': "Demsetz soutient que le mode d'organisation et de rémunération d'une activité découle directement de l'observabilité de l'apport individuel, et que le créancier résiduel est l'acteur le plus incité à l'efficacité. La thèse articule mesure et droits. Plus l'apport individuel est aisément observable, plus l'incitation peut passer par le résultat : la rémunération à la pièce suffit et la surveillance est inutile. Plus il est difficile à isoler, plus le contrôle direct doit s'y substituer, avec un salaire fixe et une hiérarchie. Et pour que le contrôleur contrôle effectivement, il faut que sa propre rémunération dépende de ce qui reste après paiement de tous les autres apporteurs : c'est le statut de créancier résiduel, qui explique pourquoi le propriétaire du capital occupe en général cette position. Il en découle un critère général : chaque mode d'organisation est efficace dans l'environnement de mesure qui lui correspond.",
  'po': "Dans le chapitre, cette analyse précise le mécanisme de l'approche contractuelle et fournit une explication économique des formes de rémunération observées. Elle permet de comprendre pourquoi le salaire fixe s'est généralisé avec le travail en équipe, et prépare l'analyse de la relation d'agence entre actionnaires et dirigeants.",
  'co': "Harold Demsetz relie le mode d'organisation à l'observabilité de l'apport individuel : la rémunération au résultat suffit lorsque la contribution est mesurable, le contrôle hiérarchique s'y substitue sinon, et le créancier résiduel, percevant ce qui reste, est le plus incité à l'efficacité.",
 },
 "Rationalité limitée dans la firme": {
  'af': "Simon soutient que les décisions de l'entreprise ne peuvent pas être modélisées comme une maximisation, et que l'organisation réelle fonctionne par routines et par niveaux d'aspiration. La thèse s'oppose à la représentation néoclassique de l'entreprise comme automate calculant l'optimum : une telle entreprise devrait connaître l'ensemble de ses options, de ses coûts et de la demande, ce qui excède les capacités d'information et de traitement de toute organisation. L'entreprise réelle procède autrement : elle applique des règles de décision éprouvées, se fixe des objectifs de niveau — un taux de marge visé, une part de marché à tenir — et ne révise ses procédures que lorsqu'un seuil n'est plus atteint. Cette architecture explique l'inertie des organisations, la dépendance des décisions à l'information disponible dans la hiérarchie, et la nécessité même de la structure hiérarchique, qui sert à découper un problème trop vaste en problèmes traitables.",
  'po': "Dans le chapitre, cette thèse fournit le fondement comportemental sans lequel les théories de la firme perdent leur objet : si les agents étaient parfaitement rationnels, les contrats seraient complets et la firme inutile. Elle est l'une des deux hypothèses explicites de Williamson et la condition de possibilité de toute l'analyse transactionnelle.",
  'co': "Herbert Simon montre que l'entreprise ne maximise pas mais procède par routines et niveaux d'aspiration : cette rationalité limitée rend les contrats nécessairement incomplets et constitue la condition de possibilité de l'analyse en termes de coûts de transaction.",
 },
 "Districts industriels et économies externes": {
  'af': "Marshall soutient que la concentration géographique d'entreprises spécialisées engendre des avantages dont aucune ne pourrait bénéficier isolément, ce qu'il nomme économies externes et qui donne naissance aux districts industriels. La thèse identifie trois mécanismes distincts. Un marché du travail local épais : la concentration d'entreprises d'un même métier attire des travailleurs qualifiés, qui trouvent facilement un employeur, ce qui réduit le risque pour les deux parties. Une base de fournisseurs spécialisés : la demande locale permet à des sous-traitants très spécialisés d'atteindre une taille rentable. Des externalités de connaissance : le savoir-faire circule par les contacts informels, la mobilité des salariés et l'imitation, de sorte que, selon la formule de Marshall, les secrets du métier sont dans l'air. Ces avantages sont externes à chaque firme et internes au territoire, ce qui explique que de petites entreprises groupées puissent rivaliser avec de grandes entreprises intégrées.",
  'po': "Dans le chapitre, cette analyse fournit l'explication de la survie des PME face à la grande entreprise et constitue l'alternative territoriale au modèle chandlérien de l'intégration. Elle montre que la taille efficace n'est pas nécessairement celle de la firme mais peut être celle du système productif local.",
  'co': "Alfred Marshall montre que la concentration géographique d'entreprises spécialisées engendre des économies externes — marché du travail qualifié, fournisseurs spécialisés, circulation informelle des savoir-faire — qui permettent à des PME groupées en district de rivaliser avec de grandes firmes intégrées.",
 },
 "Main visible, intégration et firme-réseau": {
  'af': "Chandler soutient que la grande entreprise intégrée s'est imposée parce que la coordination administrative régulait les flux mieux que le marché, mais que cette supériorité est historique et peut s'inverser. La thèse se déploie en deux temps. Premier temps : lorsque le débit de production devient élevé et que les délais comptent, la coordination par le prix est trop lente et trop incertaine ; l'entreprise intègre l'amont et l'aval et confie à des managers la planification des flux. L'avantage est la régularité, le coût est la rigidité. Second temps : dès lors que les technologies de l'information abaissent le coût de la coordination entre firmes distinctes, la firme-réseau devient compétitive ; elle conserve la coordination centrale de la conception et du pilotage mais externalise la fabrication. On passe ainsi de la main visible interne à une coordination contractuelle pilotée, ce qui montre que la frontière de la firme suit l'état des techniques de coordination.",
  'po': "Dans le chapitre, cette analyse historicise l'arbitrage coasien et explique pourquoi la grande entreprise intégrée a dominé le XXᵉ siècle avant que la firme-réseau ne s'impose. Elle fournit la transition entre les théories de la firme et l'étude des formes contemporaines d'organisation productive.",
  'co': "Alfred Chandler montre que la main visible des managers a supplanté le marché lorsque les débits élevés exigeaient une régulation continue des flux, mais que la baisse du coût de coordination entre firmes rend aujourd'hui la firme-réseau compétitive : la frontière de la firme suit l'état des techniques de coordination.",
 },
 "Théorie de l'agence appliquée à la firme": {
  'af': "Jensen soutient que l'entreprise doit être analysée comme un ensemble de relations d'agence, chaque délégation de décision engendrant des conflits d'intérêts et des coûts qu'il convient de minimiser par des contrats incitatifs. Appliquée aux questions de ce chapitre, la théorie éclaire deux problèmes précis. Le premier concerne la croissance de la firme : les dirigeants peuvent préférer l'accroissement de la taille, qui augmente leur pouvoir, leur prestige et leur rémunération, à l'accroissement de la rentabilité, ce qui explique que des acquisitions détruisant de la valeur pour l'actionnaire soient néanmoins décidées. Le second concerne la structure financière : la dette, en absorbant la trésorerie disponible et en imposant des échéances, réduit la latitude discrétionnaire du dirigeant. La croissance externe cesse ainsi d'être analysée comme une pure décision stratégique pour devenir un révélateur de la gouvernance.",
  'po': "Dans le chapitre, cette théorie fournit l'explication des opérations de croissance externe qui n'améliorent pas la performance, et montre que la stratégie d'une entreprise ne peut être comprise sans examiner qui la décide et selon quelles incitations. Elle relie l'analyse de la taille à celle du pouvoir.",
  'co': "La théorie de l'agence éclaire la croissance externe : les dirigeants peuvent privilégier la taille, qui accroît leur pouvoir et leur rémunération, sur la rentabilité, ce qui explique des acquisitions destructrices de valeur et justifie le rôle disciplinaire de l'endettement.",
 },
 "Structure financière comme instrument de discipline": {
  'af': "Meckling soutient que la manière dont une entreprise est financée n'est pas neutre sur ses décisions, parce qu'elle détermine la marge de manœuvre dont dispose le dirigeant. La thèse oppose deux régimes. Les fonds propres laissent au dirigeant la liberté d'affecter la trésorerie à sa convenance, y compris à des projets peu rentables mais valorisants. La dette l'oblige à dégager des flux réguliers sous peine de défaut, ce qui constitue un engagement crédible à ne pas gaspiller. Augmenter l'endettement est donc un instrument de gouvernance autant qu'un choix de financement. Mais Meckling en souligne aussitôt le coût : un endettement élevé accroît le risque de faillite et, lorsque la situation se dégrade, incite à prendre des risques excessifs puisque les pertes seront supportées par les créanciers. La structure financière observée résulte de cet arbitrage entre discipline et flexibilité.",
  'po': "Dans le chapitre, cette analyse montre que le financement est un déterminant des stratégies d'entreprise et explique les opérations de rachat avec effet de levier. Elle complète la théorie de l'agence en identifiant un instrument de gouvernance distinct de la rémunération incitative.",
  'co': "William Meckling montre que la structure financière est un instrument de gouvernance : la dette, en absorbant la trésorerie et en imposant des échéances, constitue un engagement crédible à ne pas gaspiller, au prix d'un risque accru de faillite et d'une incitation à la prise de risque excessive.",
 },
 "Organisation scientifique du travail et taille des entreprises": {
  'af': "Appliquée à la question de la taille, l'organisation scientifique du travail de Taylor soutient que la rationalisation accroît la productivité mais n'est rentable qu'à grande échelle, et pousse donc à la concentration industrielle. La thèse repose sur la nature des coûts qu'elle implique. L'organisation scientifique du travail exige un bureau des méthodes, des ingénieurs, un appareil de mesure et de contrôle : autant de coûts fixes qui ne s'amortissent que sur de longues séries. S'y ajoute une contrainte logique : la division poussée du travail suppose un volume d'activité suffisant pour que chaque tâche élémentaire occupe un travailleur à plein temps. Le taylorisme n'est donc pas seulement une technique de gestion du travail, c'est l'un des ressorts de la croissance de la taille des entreprises, puisqu'il rend la grande échelle plus productive que la petite.",
  'po': "Dans le chapitre, cette analyse relie organisation du travail et concentration industrielle, et fournit l'un des mécanismes économiques expliquant la croissance de la taille des firmes aux côtés des économies d'échelle techniques. Elle montre que la structure productive dépend de l'organisation autant que de la technologie.",
  'co': "L'organisation scientifique du travail suppose un bureau des méthodes et un appareil de contrôle dont les coûts fixes ne s'amortissent que sur de longues séries : le taylorisme constitue ainsi l'un des ressorts de la concentration industrielle et non seulement une technique de gestion.",
 },
 "Concurrence monopolistique et différenciation": {
  'af': "Chamberlin soutient qu'entre le monopole et la concurrence parfaite existe une structure de marché très répandue, où de nombreuses entreprises offrent des produits différenciés et disposent chacune d'un petit pouvoir de marché. La thèse repose sur la différenciation : par la qualité, la marque, le service, la localisation ou le design, chaque producteur rend son produit imparfaitement substituable à ceux de ses concurrents. La demande qui lui est adressée devient alors décroissante au lieu d'être horizontale : il peut élever légèrement son prix sans perdre toute sa clientèle, car une partie des acheteurs le préfère. Chaque firme est donc un petit monopole sur sa variété tout en subissant la concurrence des autres. Chamberlin en tire un résultat important sur l'équilibre de long terme : la libre entrée annule les profits, mais la production s'établit en deçà de la taille minimisant le coût moyen, de sorte qu'il subsiste une capacité excédentaire — prix payé pour la variété offerte au consommateur.",
  'po': "Dans le chapitre, cette analyse établit que le pouvoir de marché ne provient pas seulement de la concentration mais aussi de la différenciation, ce qui élargit considérablement le champ de la concurrence imparfaite. Elle fournit le cadre théorique permettant d'analyser la publicité, la marque et les stratégies de positionnement.",
  'co': "Edward Chamberlin montre que la différenciation des produits engendre une concurrence monopolistique : chaque firme fait face à une demande décroissante et dispose d'un pouvoir de marché sur sa variété, la libre entrée annulant les profits au prix d'une capacité excédentaire.",
 },
 "Marchés contestables : la menace d'entrée discipline les prix": {
  'af': "Baumol soutient que ce n'est pas le nombre d'entreprises présentes sur un marché qui garantit la concurrence mais la liberté d'y entrer et d'en sortir, de sorte qu'un marché très concentré peut rester parfaitement concurrentiel s'il est contestable. La thèse définit précisément les conditions de la contestabilité : l'entrée doit être libre, l'entrant doit accéder à la même technologie, et il ne doit pas exister de coûts irrécupérables importants, c'est-à-dire de dépenses perdues en cas de sortie. Lorsque ces conditions sont réunies, un monopole en place qui fixerait un prix supérieur à son coût attirerait un entrant venant prélever le surprofit avant de repartir — c'est la stratégie du hit and run. L'anticipation de cette entrée suffit à contraindre le monopoleur à pratiquer un prix concurrentiel, sans qu'aucune entrée n'ait besoin d'avoir lieu. Le critère pertinent de la politique de concurrence se déplace ainsi de l'atomicité vers les barrières.",
  'po': "Dans le chapitre, cette thèse renverse le modèle Structure-Comportements-Performances en brisant le lien automatique entre concentration et pouvoir de marché. Elle fournit l'argument théorique qui explique pourquoi les autorités de concurrence n'interdisent pas les positions dominantes en tant que telles mais en sanctionnent l'abus.",
  'co': "William Baumol établit qu'un marché est contestable si l'entrée et la sortie sont libres et sans coûts irrécupérables : la seule menace d'entrée suffit alors à discipliner les prix, de sorte qu'un marché concentré peut demeurer concurrentiel et que le critère pertinent devient la barrière, non le nombre d'offreurs.",
 },
 "Du critère d'atomicité au critère de libre entrée": {
  'af': "Panzar contribue à établir la cohérence formelle de la théorie des marchés contestables et à en tirer la conséquence méthodologique : le critère de la concurrence doit être déplacé du nombre d'offreurs vers l'absence d'obstacle à l'entrée. La thèse montre que, si l'entrée et la sortie sont sans coût, la configuration d'équilibre d'un marché contestable soutient des prix égaux aux coûts quel que soit le nombre d'entreprises effectivement présentes, y compris lorsqu'il n'y en a qu'une. Le nombre d'offreurs devient alors une variable endogène, déterminée par la technologie et la taille du marché, et non un indicateur du degré de concurrence. Le corollaire pratique est important pour l'action publique : la politique de concurrence doit cibler les barrières à l'entrée plutôt que les parts de marché, ce qui change à la fois son diagnostic et ses instruments.",
  'po': "Dans le chapitre, cette précision formalise le renversement opéré par la théorie de la contestabilité et fournit le fondement de l'approche élargie de la concurrence que Combe opposera à l'approche standard. Elle montre qu'un même marché peut être jugé concurrentiel ou non selon le critère retenu.",
  'co': "John Panzar contribue à déplacer le critère de la concurrence de l'atomicité vers la libre entrée : le nombre d'offreurs étant déterminé par la technologie et la taille du marché, la politique de concurrence doit cibler les barrières à l'entrée plutôt que les parts de marché.",
 },
 "Un marché concentré peut rester concurrentiel": {
  'af': "Willig soutient que le lien entre concentration et pouvoir de marché n'est pas mécanique, et qu'une même part de marché peut être inoffensive ou nuisible selon les conditions d'entrée. La thèse précise ce qui relie effectivement la structure aux performances : non pas le nombre d'acteurs, mais la possibilité pour un entrant de contester la position en place. Cette possibilité dépend de trois éléments : la technologie, c'est-à-dire le degré de coûts irrécupérables requis pour entrer ; le cadre réglementaire, qui peut créer ou lever des barrières ; et l'accès aux ressources essentielles, infrastructures ou réseaux dont la maîtrise peut verrouiller un marché. L'analyse justifie une méthode d'examen au cas par cas plutôt que l'application de seuils, ce qui correspond à la pratique effective des autorités de concurrence.",
  'po': "Dans le chapitre, cette analyse achève la critique du modèle SCP et fournit la justification théorique de l'examen au cas par cas des concentrations. Elle permet de comprendre pourquoi un taux de refus de fusion très faible n'est pas nécessairement le signe d'une politique de concurrence défaillante.",
  'co': "Robert Willig souligne que la concentration ne détermine pas mécaniquement le pouvoir de marché : tout dépend des coûts irrécupérables, du cadre réglementaire et de l'accès aux ressources essentielles, ce qui justifie un examen au cas par cas plutôt que l'application de seuils.",
 },
 "Origine du modèle Structure-Comportements-Performances": {
  'af': "Mason pose la causalité fondatrice de l'économie industrielle : la structure d'un marché conditionne les comportements des entreprises qui y opèrent, lesquels déterminent à leur tour leurs performances. La thèse établit une méthode d'analyse ordonnée des marchés réels, par opposition au raisonnement abstrait sur la concurrence parfaite. La structure rassemble le nombre d'offreurs, le degré de concentration, la différenciation des produits et les barrières à l'entrée : elle détermine le degré de liberté stratégique dont chaque entreprise dispose. Les comportements — politique de prix, publicité, innovation, entente — en découlent. Les performances — rentabilité, efficacité allocative, progrès technique — résultent de ces comportements. L'intérêt du modèle est de fournir une grille d'observation applicable à tout marché concret, et c'est à ce titre qu'il fonde l'économie industrielle comme discipline.",
  'po': "Dans le chapitre, ce modèle fournit la grille d'analyse de référence des marchés et une structure de raisonnement en trois temps directement utilisable. Il constitue le cadre dominant que la théorie de la contestabilité viendra contester, ce qui en fait le pivot de la discussion.",
  'co': "Le modèle Structure-Comportements-Performances, dont Edward Mason est à l'origine, établit que la configuration d'un marché — concentration, différenciation, barrières — détermine les stratégies des firmes, lesquelles déterminent à leur tour leurs résultats.",
 },
 "Modèle SCP et barrières à l'entrée": {
  'af': "Bain systématise le modèle Structure-Comportements-Performances et identifie dans les barrières à l'entrée son élément déterminant. La thèse recense les sources de ces barrières : les économies d'échelle, qui imposent une taille minimale d'efficience ; la différenciation acquise et la fidélité à la marque, qui obligent l'entrant à des dépenses commerciales considérables ; les avantages absolus de coût d'un acteur installé, liés à l'expérience ou à l'accès privilégié à une ressource ; et les besoins de capitaux initiaux. Plus ces barrières sont élevées, plus les profits des firmes installées peuvent demeurer durablement supérieurs au niveau concurrentiel sans attirer d'entrants. Bain identifie également la limite du modèle, qui deviendra la critique principale : la causalité peut s'inverser, puisqu'une entreprise qui innove ou investit massivement en publicité modifie elle-même la structure du marché.",
  'po': "Dans le chapitre, cette formalisation fournit la liste des barrières à l'entrée utilisable dans l'analyse de tout marché, et contient en germe sa propre critique : si la stratégie transforme la structure, la causalité du modèle n'est plus univoque. C'est ce renversement qui ouvre la discussion avec la théorie de la contestabilité.",
  'co': "Joe Bain systématise le modèle SCP en identifiant les barrières à l'entrée — économies d'échelle, différenciation acquise, avantages absolus de coût, besoins de capitaux — comme l'élément déterminant, tout en reconnaissant que la stratégie des firmes peut en retour modifier la structure du marché.",
 },
 "Indice de Lerner : mesurer le pouvoir de marché": {
  'af': "L'indice de Lerner mesure le pouvoir de marché d'une entreprise par l'écart relatif entre son prix et son coût marginal, selon la formule L = (P – Cm) / P. La thèse qui le fonde est qu'un tel écart n'est possible que si l'entreprise dispose d'un pouvoir de fixation du prix. En concurrence parfaite, l'entreprise est preneuse de prix et produit jusqu'à égaliser son prix et son coût marginal : l'indice vaut zéro. Dès qu'elle détient un pouvoir de marché, elle restreint sa production pour vendre plus cher, et le prix s'écarte du coût marginal : l'indice s'élève et tend vers un lorsque le pouvoir est maximal. L'indice mesure donc la part de la marge dans le prix. Il est par ailleurs inversement lié à l'élasticité-prix de la demande adressée à la firme : plus la demande est inélastique, plus l'entreprise peut s'écarter du coût marginal. Sa limite pratique est que le coût marginal n'est pas directement observable.",
  'po': "Dans le chapitre, cet indice fournit l'instrument de mesure qui permet de passer du constat qualitatif d'un pouvoir de marché à sa quantification. Il articule la différenciation, qui réduit l'élasticité, et le pouvoir de marché, qui en résulte, et donne un contenu mesurable aux performances du modèle SCP.",
  'co': "L'indice de Lerner, L = (P – Cm) / P, mesure le pouvoir de marché par la part de la marge dans le prix : nul en concurrence parfaite, il s'élève à mesure que la demande adressée à la firme devient inélastique, mais se heurte à la difficulté d'observer le coût marginal.",
 },
 "Cartels, politique de concurrence et approche élargie": {
  'ti': "Les cartels : durée, effets et instabilité",
  'af': "Combe soutient, sur la base d'une étude de 111 cartels observés entre 1969 et 2009, que les ententes ne sont ni rares ni éphémères : elles sont souvent durables, elles élèvent effectivement les prix et elles se forment principalement sur des marchés oligopolistiques. La thèse combine un constat empirique et une analyse théorique. Le constat : la durée moyenne des cartels est longue, leur effet sur les prix est significatif, et leur fréquence est d'autant plus grande que le nombre d'acteurs est faible, puisque la coordination y est plus facile à établir et à surveiller. L'analyse : le cartel est pourtant structurellement instable, car chaque membre a intérêt à tricher en vendant légèrement en dessous du prix convenu pour capter des parts de marché. Cette structure est exactement celle du dilemme du prisonnier, et c'est elle qui explique l'efficacité de la procédure de clémence, laquelle exploite la défiance mutuelle en récompensant le premier dénonciateur.",
  'po': "Dans le chapitre, cette analyse fournit le contenu empirique de l'étude des ententes et montre que la politique de concurrence dispose d'un instrument adapté à la nature même du problème. Elle illustre un principe général : la connaissance du mécanisme d'un comportement permet de concevoir l'instrument qui le défait.",
  'co': "Emmanuel Combe établit, sur 111 cartels étudiés entre 1969 et 2009, que les ententes sont durables, élèvent les prix et prospèrent sur les marchés oligopolistiques, tout en demeurant structurellement instables : cette configuration de dilemme du prisonnier explique l'efficacité de la procédure de clémence.",
 },
 "Standard Oil : le trust et ses limites": {
  'af': "Le cas de la Standard Oil illustre à la fois la puissance d'un trust capable de dominer toute une filière et les limites du démantèlement comme réponse. Rockefeller construit à partir de 1870 une position dominante par intégration verticale — raffinage, transport, distribution — et par des accords avec les compagnies ferroviaires lui garantissant des tarifs préférentiels qui asphyxient ses concurrents. Le trust est démantelé en 1911 en application des lois antitrust américaines. Mais l'enseignement le plus intéressant est postérieur : dans les années 1990, plusieurs sociétés issues de cette scission fusionnent à nouveau. Le démantèlement traite donc la structure sans supprimer les forces qui l'avaient produite — économies d'échelle, avantages de l'intégration, contrôle des infrastructures essentielles. Un remède structurel peut ainsi être réversible si les déterminants économiques de la concentration demeurent inchangés.",
  'po': "Dans le chapitre, ce cas historique permet d'évaluer concrètement les instruments de la politique de concurrence et de poser la question la plus actuelle qui soit, celle du démantèlement des grandes plateformes. Il montre que l'efficacité d'un remède dépend de sa capacité à agir sur les causes et non seulement sur les effets.",
  'co': "Le démantèlement de la Standard Oil en 1911 puis la refusion de plusieurs de ses héritières dans les années 1990 montrent les limites d'un remède structurel : séparer les entreprises ne supprime pas les économies d'échelle et les avantages d'intégration qui avaient produit la concentration.",
 },
 "General Electric : la logique du conglomérat": {
  'af': "La direction de General Electric par Jack Welch illustre la logique managériale du conglomérat diversifié, fondée sur les acquisitions, les restructurations permanentes et une pression continue sur les coûts et les effectifs. Le conglomérat se justifie par deux arguments qu'il faut énoncer avant de les discuter : la diversification réduirait le risque global du groupe, et la direction générale allouerait le capital entre divisions mieux que ne le ferait le marché financier. Les limites en sont cependant connues. Le premier argument est faible, car l'actionnaire peut diversifier lui-même son portefeuille à moindre coût, de sorte que la diversification ne crée pas de valeur pour lui. Le second se heurte à la compétence : une direction générale maîtrise rarement des activités très différentes. D'où la décote de conglomérat observée sur les marchés et les démantèlements ultérieurs de nombreux groupes diversifiés.",
  'po': "Dans le chapitre, ce cas permet d'examiner la concentration conglomérale, troisième forme de concentration après l'horizontale et la verticale, et d'en évaluer la rationalité économique. Il montre que la croissance de la taille n'est pas toujours justifiée par l'efficacité, ce qui renvoie aux coûts d'agence analysés par Jensen.",
  'co': "Le conglomérat diversifié se justifie par la réduction du risque et par une allocation interne du capital supposée supérieure au marché : l'actionnaire pouvant diversifier lui-même son portefeuille à moindre coût, ces arguments expliquent mal la décote de conglomérat et les démantèlements ultérieurs.",
 },
}

SPLIT[9] = [
 ('Emmanuel Combe', "Approche standard et approche élargie de la concurrence", {
  'affirme': "Combe oppose deux conceptions de la concurrence qui conduisent à des diagnostics et à des politiques différents. L'approche standard, héritée du modèle de concurrence parfaite, évalue l'intensité concurrentielle par l'atomicité, c'est-à-dire par le nombre d'offreurs et le degré de concentration : un marché concentré y est présumé peu concurrentiel. L'approche élargie, issue de la théorie de la contestabilité, évalue cette intensité par la liberté d'entrée et de sortie : un marché concentré peut y être jugé concurrentiel si rien n'empêche un entrant de contester la position établie. La thèse est que les autorités de concurrence ont largement adopté la seconde, ce qui explique un fait souvent mal interprété : environ 1 % seulement des opérations de fusion ont été refusées entre 2010 et 2020. Ce taux ne traduit pas une passivité mais un critère d'évaluation différent, centré sur les effets anticipés plutôt que sur la structure.",
  'mecanisme': "Le passage d'une approche à l'autre modifie toute la chaîne du raisonnement. Premièrement, le diagnostic : l'approche standard conclut du niveau de concentration à l'existence d'un pouvoir de marché, l'approche élargie exige de démontrer que ce pouvoir peut être exercé durablement, ce qui suppose des barrières à l'entrée. Deuxièmement, l'objet du contrôle : la première surveille les parts de marché, la seconde les comportements d'éviction et les obstacles à l'entrée. Troisièmement, les remèdes : la première privilégie les remèdes structurels, cessions d'actifs ou interdiction de fusion ; la seconde privilégie les remèdes comportementaux, engagements d'accès, interdiction de clauses d'exclusivité. Quatrièmement, le critère d'évaluation final : le bien-être du consommateur, apprécié par les prix, la qualité et l'innovation, plutôt que la préservation d'une structure concurrentielle en elle-même.",
  'exemple': "Une fusion entre deux acteurs importants d'un secteur peut être autorisée si l'autorité estime que l'entrée demeure possible et que des engagements d'accès suffisent à préserver la contestabilité, alors qu'un raisonnement fondé sur les seules parts de marché l'aurait interdite.",
  'diss': "Référence décisive sur « faut-il lutter contre la concentration ? », « la politique de concurrence est-elle efficace ? », « comment apprécier la concurrence ? ». Place : deuxième ou troisième partie, pour montrer que le désaccord sur les conclusions provient d'un désaccord sur le critère, et non d'un désaccord sur les faits.",
  'portee': "Dans le chapitre, cette opposition organise toute la partie consacrée aux politiques de concurrence : elle explique pourquoi les autorités n'interdisent pas les positions dominantes mais en sanctionnent l'abus, et fournit la clé d'interprétation du faible taux de refus des concentrations.",
  'copie': "Emmanuel Combe oppose une approche standard de la concurrence, fondée sur l'atomicité et la concentration, à une approche élargie fondée sur la contestabilité : ce changement de critère explique que les autorités sanctionnent l'abus de position dominante plutôt que la position elle-même, et que près de 99 % des fusions aient été autorisées entre 2010 et 2020.",
  'ouvrage': "La politique de la concurrence (2016)",
  'notions': ['approche élargie', 'contestabilité', 'contrôle des concentrations', 'remèdes comportementaux', 'bien-être du consommateur'],
  'liens': [('William Baumol', 'prolonge', "L'approche élargie applique le critère de contestabilité à la politique de concurrence."),
            ('Joe Bain', 'opposition', "Le modèle SCP fonde l'approche standard que Combe met en regard de l'approche élargie."),
            ('George Stigler', 'complement', "Le risque de capture rappelle que le choix du critère n'est pas purement technique.")],
 }),
]

ENR[10] = {
 'Bureaucratie, types de domination et rationalisation': {
  'ti': 'Les trois types de domination légitime',
  'af': "Weber soutient que toute autorité repose sur une croyance en sa légitimité, et il distingue trois types purs selon le fondement de cette croyance. La domination traditionnelle s'appuie sur le caractère sacré de coutumes immémoriales : on obéit parce qu'il en a toujours été ainsi, et le détenteur du pouvoir est désigné par la tradition. La domination charismatique s'appuie sur les qualités extraordinaires attribuées à une personne : on obéit à un individu en raison de ce qu'il est, et cette forme est par nature instable puisqu'elle disparaît avec lui. La domination rationnelle-légale s'appuie sur la croyance en la validité de règles établies : on obéit à une fonction et non à une personne, dans les limites que la règle fixe. Weber ne soutient pas que ces types se succèdent mécaniquement mais que la modernité est caractérisée par la prédominance croissante du troisième, dont l'organisation bureaucratique constitue l'expression accomplie.",
  'po': "Dans le chapitre, cette typologie ouvre l'analyse sociologique des organisations en posant la question du fondement de l'obéissance, préalable à toute étude du pouvoir. Elle fournit un instrument de comparaison applicable à l'entreprise, à l'administration et à toute organisation, et prépare la critique de Crozier, qui montrera que le pouvoir réel ne coïncide pas avec l'autorité légitime.",
  'co': "Max Weber distingue trois types de domination légitime — traditionnelle, charismatique et rationnelle-légale — selon le fondement de la croyance en la légitimité : la modernité se caractérise par la prédominance de la troisième, où l'on obéit à une fonction définie par des règles et non à une personne.",
 },
 'Division du travail social, solidarité et anomie': {
  'ti': 'Division du travail social et formes de solidarité',
  'af': "Durkheim soutient que la division du travail ne produit pas seulement de la richesse, comme le voulait Smith, mais une forme nouvelle de lien social. Sa thèse distingue deux types de solidarité. La solidarité mécanique repose sur la ressemblance : dans les sociétés traditionnelles, les individus peu différenciés partagent croyances et pratiques, et c'est l'intensité de cette conscience collective qui les relie. La solidarité organique repose sur la complémentarité : la spécialisation rend chacun dépendant des autres pour ce qu'il ne produit pas lui-même, et c'est cette interdépendance qui fait tenir la société. Durkheim en tire une conséquence majeure pour l'analyse du travail : celui-ci intègre de trois manières complémentaires — il crée des relations, il rattache à un groupe, il fournit des normes et un cadre temporel. Le travail n'est donc pas seulement un moyen de subsistance mais un opérateur d'intégration sociale.",
  'me': "Le raisonnement procède par comparaison historique et par analyse fonctionnelle. Premièrement, Durkheim observe que l'intensification de la division du travail accompagne l'accroissement du volume et de la densité des sociétés : plus les individus sont nombreux et en contact, plus la concurrence pour les mêmes ressources les pousse à se spécialiser. Deuxièmement, cette spécialisation affaiblit la conscience collective, puisque les expériences individuelles divergent ; la solidarité mécanique recule. Troisièmement, elle crée en retour une dépendance réciproque : chacun ayant besoin des autres, un lien d'un type nouveau se forme. Quatrièmement, ce lien n'est pas automatique, et c'est le point décisif : il suppose que la division du travail soit régulée, que les échanges soient encadrés par des règles reconnues et que les positions correspondent aux capacités. À défaut, la division du travail produit de la désorganisation au lieu de la solidarité.",
  'ex': "Le chômage de longue durée illustre les trois fonctions intégratrices par leur disparition simultanée : perte des relations professionnelles, perte du rattachement à un collectif de travail, perte des normes temporelles qui structuraient la journée et la semaine.",
  'po': "Dans le chapitre, cette analyse fonde l'approche sociologique du travail et fournit le critère au regard duquel seront évaluées ensuite la précarisation et la désaffiliation. Elle oppose en outre un holisme méthodologique à l'individualisme des économistes, ce qui en fait l'un des deux pôles méthodologiques du programme.",
  'co': "Émile Durkheim distingue la solidarité mécanique, fondée sur la ressemblance, de la solidarité organique, fondée sur la complémentarité d'individus spécialisés : le travail intègre parce qu'il crée des relations, rattache à un groupe et fournit des normes, à condition que la division du travail soit régulée.",
 },
 'Effet Hawthorne et école des relations humaines': {
  'af': "Mayo soutient que la productivité ne dépend pas seulement des conditions matérielles de travail et des incitations monétaires mais de l'attention portée aux travailleurs et de la qualité des relations au sein du groupe. La thèse résulte d'un résultat inattendu obtenu lors des enquêtes menées à la Western Electric à partir des années 1920 : en faisant varier l'éclairage de l'atelier, les chercheurs constatent que la productivité augmente, puis qu'elle continue d'augmenter lorsqu'on diminue l'éclairage. L'expérience de la Test Room confirme que la variable efficace n'est pas celle que l'on manipule mais le fait d'être observé, consulté et constitué en groupe distinct. Deux conséquences en découlent. Méthodologiquement, l'observateur modifie le comportement observé : c'est l'effet Hawthorne. Théoriquement, l'entreprise doit être analysée comme un système social doté de normes informelles propres, et non comme un simple agencement technique.",
  'po': "Dans le chapitre, cette analyse fonde l'École des relations humaines et constitue la première critique empirique du taylorisme : elle ne conteste pas la recherche de productivité mais la conception du travailleur sur laquelle elle repose. Elle ouvre la voie à l'étude du monde informel que Crozier transformera en analyse du pouvoir.",
  'co': "Les enquêtes de la Western Electric conduites par Elton Mayo établissent l'effet Hawthorne : la productivité augmente du fait même de l'attention portée aux ouvriers, ce qui impose d'analyser l'entreprise comme un système social doté de normes informelles et non comme un agencement technique.",
 },
 'Organisation scientifique du travail et déshumanisation': {
  'af': "Examinée sous l'angle sociologique, l'organisation scientifique du travail de Taylor accroît la productivité en dépossédant l'ouvrier de son savoir-faire et du sens de son activité. La thèse articule les quatre opérations du taylorisme à leurs effets sociaux. La division verticale retire à l'ouvrier la maîtrise de sa méthode, donc son autonomie et son pouvoir de négociation sur la cadence. La division horizontale réduit son activité à un geste répétitif dont il ne perçoit plus la finalité. Le chronométrage transforme un temps vécu en temps mesuré et imposé. Le salaire au rendement individualise le rapport au travail et défait les solidarités d'atelier. Il en résulte des pathologies caractéristiques — monotonie, fatigue nerveuse, rotation du personnel, conflictualité — et une perte de sens que la sociologie du travail documentera. La résistance ouvrière n'est donc pas une irrationalité mais la défense d'une maîtrise.",
  'po': "Dans le chapitre, cette lecture critique du taylorisme fournit le cas d'école d'une organisation efficace et socialement coûteuse, et permet de poser la question qui traverse toute la sociologie du travail : à quelles conditions le travail intègre-t-il, et à quelles conditions dégrade-t-il ? Elle appelle directement la réponse de Mayo.",
  'co': "L'organisation scientifique du travail dépossède l'ouvrier de son savoir-faire par la division verticale, réduit son activité à un geste répétitif et transforme le temps vécu en temps mesuré : le freinage collectif de la production constitue dès lors une réponse rationnelle et non un refus irrationnel du progrès.",
 },
 'Travail, exploitation et aliénation': {
  'af': "Marx soutient que dans le rapport salarial capitaliste le travailleur perd la maîtrise de son activité comme de son produit, de sorte que le travail, qui devrait être réalisation de soi, devient aliénation. La thèse comporte une dimension économique et une dimension sociale indissociables. Économiquement, la plus-value est le surplus produit par le travailleur au-delà de la valeur de sa force de travail et approprié par le propriétaire des moyens de production. Socialement, l'aliénation se décline en quatre séparations : le travailleur est séparé de son produit, qui lui devient étranger et lui fait face comme une puissance extérieure ; séparé de son activité, dont il ne choisit ni le rythme ni la méthode ; séparé des autres, mis en concurrence avec eux ; séparé enfin de lui-même, puisque l'activité la plus propre à l'homme lui devient extérieure. Cette grille fournit un critère d'évaluation applicable à toute organisation du travail : le degré de maîtrise qu'elle laisse au travailleur.",
  'po': "Dans le chapitre, cette analyse fournit l'outil critique le plus général pour évaluer les formes d'organisation du travail, du taylorisme aux plateformes numériques. Elle complète Durkheim en montrant que le travail peut aussi désintégrer, et fournit le fondement théorique des analyses de la précarisation étudiées en fin de chapitre.",
  'co': "Pour Marx, l'aliénation désigne quatre séparations : le travailleur est séparé de son produit, de son activité, des autres travailleurs et de lui-même — grille qui fournit un critère d'évaluation applicable à toute organisation du travail, du taylorisme au travail de plateforme.",
 },
 "Analyse stratégique, zone d'incertitude et cercle vicieux bureaucratique": {
  'ti': "Analyse stratégique : le pouvoir naît de la zone d'incertitude",
  'af': "Crozier soutient que le pouvoir dans une organisation n'est pas celui que décrit l'organigramme : il appartient à qui contrôle une zone d'incertitude, c'est-à-dire ce dont les autres dépendent et qu'ils ne maîtrisent pas. La thèse repose sur une distinction entre le monde formel des règles et le monde informel des relations réelles. Toute règle, si minutieuse soit-elle, laisse subsister des zones d'incertitude — pannes, aléas, cas non prévus, marges d'interprétation — et celui qui les maîtrise détient un pouvoir réel, quel que soit son rang hiérarchique. Les acteurs ne sont ni irrationnels ni passifs : ils poursuivent des stratégies en utilisant leur marge de manœuvre, et protègent soigneusement la zone qui fonde leur pouvoir. Le pouvoir est donc relationnel et non substantiel : il ne se possède pas, il s'exerce dans une relation d'échange déséquilibrée dont chaque partie tire quelque chose.",
  'me': "Le raisonnement se construit à partir de l'enquête. Premièrement, Crozier observe que dans l'entreprise qu'il nomme le monopole industriel — en réalité la SEITA — tout est réglé à l'avance, à une exception près : la panne des machines, par nature imprévisible. Deuxièmement, les ouvriers d'entretien, seuls capables de les réparer, détiennent de ce fait un pouvoir considérable sur les chefs d'atelier, dont la production dépend d'eux. Troisièmement, ce pouvoir n'est pas conféré par la hiérarchie mais par la maîtrise d'une incertitude, de sorte qu'il est rationnel pour ces ouvriers d'entretenir cette incertitude : ils ne documentent pas leur savoir et transmettent oralement. Quatrièmement, la direction, constatant le dysfonctionnement, édicte de nouvelles règles ; mais chaque règle supprime une incertitude et en crée d'autres ailleurs, de sorte que de nouveaux jeux de pouvoir apparaissent.",
  'ex': "Les ouvriers d'entretien de la SEITA tirent leur pouvoir de la maîtrise exclusive de la réparation des machines : ils ont intérêt à ce que la panne reste imprévisible et le savoir non écrit, ce qui est parfaitement rationnel de leur point de vue et incompréhensible du point de vue de l'organigramme.",
  'po': "Dans le chapitre, cette analyse constitue la critique décisive du modèle wébérien : la bureaucratie réelle n'est pas l'organisation rationnelle que décrit le type idéal, parce qu'elle est peuplée d'acteurs stratèges. Elle fournit la méthode d'analyse des organisations que le chapitre applique ensuite aux décisions absurdes et aux phénomènes de groupe.",
  'co': "Michel Crozier montre que le pouvoir appartient à qui contrôle une zone d'incertitude : les ouvriers d'entretien de la SEITA, seuls capables de réparer les machines, détiennent sur la hiérarchie un pouvoir réel qu'aucun organigramme ne prévoit et qu'ils ont intérêt à préserver.",
 },
 "L'acteur et le système": {
  'af': "Friedberg soutient que l'organisation doit être analysée comme un construit social, c'est-à-dire comme le résultat contingent de l'ajustement des stratégies de ses membres, et non comme un ensemble de règles qui détermineraient leurs comportements. La thèse insiste sur la circularité entre l'acteur et le système. L'organisation n'est ni une structure qui commanderait les conduites, ni une simple somme d'individus libres : elle est un jeu dont les règles effectives — distinctes des règles officielles — résultent des stratégies passées et contraignent les stratégies futures. Comprendre une organisation suppose donc de partir des acteurs réels, d'identifier les ressources dont chacun dispose et les contraintes qu'il subit, puis de reconstituer les règles du jeu effectivement pratiquées. La conséquence pratique est décisive : une réforme imposée d'en haut sans tenir compte de ces jeux sera absorbée, détournée ou vidée de son contenu.",
  'po': "Dans le chapitre, cette analyse généralise l'apport de Crozier en méthode d'étude des organisations et explique pourquoi les réformes organisationnelles échouent si fréquemment. Elle fournit l'argument central des sujets portant sur le changement dans les organisations.",
  'co': "Erhard Friedberg analyse l'organisation comme un construit social : les règles effectives résultent de l'ajustement des stratégies des acteurs, de sorte qu'une réforme décidée sans eux est généralement absorbée par les jeux existants.",
 },
 'Décisions absurdes et métarègles': {
  'af': "Morel soutient que des organisations rationnelles, composées d'individus compétents et de bonne foi, produisent régulièrement des décisions absurdes, et que cette absurdité est une œuvre collective et non une faute individuelle. La thèse identifie trois familles de causes. Les causes individuelles : crainte de contredire l'autorité, autocensure, souci de ne pas paraître incompétent en posant une question. Les causes collectives : conformisme, recherche d'unanimité, et surtout dilution de la responsabilité, personne ne se sentant comptable d'une décision prise par tous. Les causes cognitives : fixation sur une hypothèse initiale, mauvaise interprétation de signaux ambigus, erreurs de représentation. Morel en tire des remèdes qu'il nomme métarègles, c'est-à-dire des règles portant sur la manière de décider plutôt que sur le contenu de la décision : débat contradictoire organisé, désignation d'un avocat du diable, droit reconnu à tout membre d'interrompre une opération, non-punition de l'erreur signalée afin que l'information circule.",
  'po': "Dans le chapitre, cette analyse fournit le versant constructif de la sociologie des organisations : après Crozier, qui décrit les dysfonctionnements, Morel propose des dispositifs pour les prévenir. Elle synthétise les apports cognitifs de Kahneman et les apports collectifs d'Asch et de Janis en une théorie de la décision organisationnelle.",
  'co': "Christian Morel montre que les décisions absurdes sont une œuvre collective, produite par la déférence hiérarchique, le conformisme, la dilution de la responsabilité et des biais cognitifs : il y oppose des métarègles portant sur la manière de décider, comme le débat contradictoire ou la non-punition de l'erreur signalée.",
 },
 "Conformisme : le paradigme d'Asch": {
  'af': "Asch établit expérimentalement qu'un individu peut adopter publiquement une réponse qu'il sait fausse sous l'effet de la pression du groupe, et que le conformisme n'exige donc ni ignorance ni contrainte. Le dispositif est d'une simplicité délibérée : il s'agit de comparer la longueur de lignes, tâche sans aucune ambiguïté perceptive. Lorsque plusieurs complices donnent à l'unanimité une réponse manifestement erronée, une proportion importante de sujets s'y rallie. Deux ressorts sont à l'œuvre, qu'il convient de distinguer : l'influence informationnelle, par laquelle le sujet doute de sa propre perception puisque tous les autres voient autre chose, et l'influence normative, par laquelle il redoute le coût social de la singularité. Le résultat le plus important pour l'analyse des organisations est qu'un seul allié dissident fait chuter massivement le taux de conformité : ce n'est pas le nombre d'opposants qui compte, c'est l'unanimité apparente.",
  'po': "Dans le chapitre, cette expérience fournit le fondement empirique de l'analyse des phénomènes de groupe dans la décision, et explique pourquoi des réunions composées de personnes compétentes aboutissent à des choix que chacune réprouvait. Son résultat sur le dissident unique fonde directement les métarègles de Morel.",
  'co': "L'expérience d'Asch établit le pouvoir du conformisme : sur une tâche perceptive sans ambiguïté, une part importante des sujets se rallie à une réponse unanime manifestement fausse — mais la présence d'un seul dissident fait chuter massivement cette conformité.",
 },
 'Groupthink : la pensée de groupe': {
  'af': "Janis soutient que dans un groupe très cohésif la recherche d'unanimité peut l'emporter sur l'examen critique des options et dégrader gravement la qualité de la décision. La thèse identifie les symptômes du groupthink : illusion d'invulnérabilité, rationalisation collective des objections, croyance en la supériorité morale du groupe, stéréotypes dépréciatifs sur les adversaires, pression exercée sur les dissidents, autocensure de ceux qui doutent, illusion d'unanimité, et apparition de gardiens de la pensée qui filtrent les informations dérangeantes avant qu'elles n'atteignent le groupe. Le caractère pervers du mécanisme tient à ce qu'il se nourrit de qualités apparentes — la cohésion, la loyauté, la confiance dans le chef — ce qui conduit à un paradoxe que l'analyse des organisations doit intégrer : des équipes brillantes et soudées prennent parfois de plus mauvaises décisions qu'un groupe hétérogène et conflictuel.",
  'po': "Dans le chapitre, cette analyse complète celle d'Asch en montrant comment le conformisme opère dans les groupes de décision réels, et fournit une liste de symptômes directement observable. Elle établit que la cohésion d'une équipe, généralement présentée comme une vertu organisationnelle, comporte un risque propre.",
  'co': "Irving Janis décrit le groupthink : dans un groupe cohésif, la recherche d'unanimité engendre autocensure, filtrage de l'information et illusion d'unanimité, de sorte que la cohésion, habituellement tenue pour une vertu, dégrade la qualité de la décision.",
 },
 'Marché cognitif, avarice cognitive et démocratie des crédules': {
  'af': "Bronner soutient que l'information circule sur un marché cognitif où se rencontrent une offre et une demande de croyances, et que la dérégulation de ce marché par Internet ne fait pas progresser automatiquement la rationalité collective. La thèse combine trois éléments. Du côté de la demande, l'avarice cognitive : l'esprit humain économise son effort et privilégie les explications simples, immédiatement intelligibles et émotionnellement satisfaisantes — ce que Bronner rapproche explicitement du système 1 de Kahneman. Du côté de l'offre, la dérégulation : la disparition des intermédiaires qui filtraient l'information met en concurrence directe des contenus très inégalement fiables. Du côté des mécanismes de diffusion, la logique d'audience : ce qui retient l'attention n'est pas ce qui est vrai mais ce qui est frappant, et les contenus croyants sont souvent plus motivés et plus prolifiques que les contenus scientifiques, naturellement prudents et nuancés.",
  'po': "Dans le chapitre, cette analyse étend la sociologie cognitive au-delà de l'organisation et montre que les mécanismes de formation des croyances obéissent à une logique économique d'offre et de demande. Elle relie les biais individuels étudiés avec Kahneman aux phénomènes collectifs étudiés avec Asch et Janis.",
  'co': "Gérald Bronner analyse le marché cognitif comme la rencontre d'une offre et d'une demande d'informations : l'avarice cognitive de la demande, la dérégulation de l'offre et la logique d'audience favorisent les contenus les plus attractifs, non les plus fiables.",
 },
 'Système 1 et biais dans les décisions organisationnelles': {
  'af': "Appliquée aux organisations, l'analyse de Kahneman soutient que les décisions collectives sont exposées aux mêmes biais systématiques que les décisions individuelles, et que le contexte organisationnel les amplifie au lieu de les corriger. Le système 1 produit des jugements immédiats, cohérents et confiants à partir d'informations disponibles et saillantes. En organisation, plusieurs biais s'y ajoutent avec une intensité particulière : l'ancrage, par lequel le premier chiffre avancé en réunion structure toute la discussion ultérieure ; l'excès de confiance dans les prévisions, renforcé par l'exigence de paraître assuré ; l'escalade d'engagement, qui pousse à persévérer dans un projet pour ne pas avoir à reconnaître une erreur ; la disponibilité, qui fait surestimer les risques récemment médiatisés. Le point décisif est que ces biais, étant systématiques et partagés, ne se compensent pas entre participants : la délibération collective peut les renforcer.",
  'po': "Dans le chapitre, cette analyse fournit le versant cognitif de l'explication des décisions absurdes, que Morel combine aux causes individuelles et collectives. Elle montre que la rationalité organisationnelle est doublement limitée, cognitivement et socialement, ce qui justifie des dispositifs de procédure plutôt que l'appel à la vigilance des participants.",
  'co': "Appliqués à l'organisation, les biais décrits par Kahneman s'amplifient : l'ancrage structure la discussion autour du premier chiffre avancé, l'escalade d'engagement fait persévérer dans l'erreur, et ces biais, étant partagés, ne se compensent pas entre les participants d'une délibération.",
 },
 'Décision en organisation sous rationalité limitée': {
  'af': "March soutient que la décision en organisation ne suit pas le modèle du choix rationnel, et qu'elle résulte de la rencontre largement contingente de problèmes, de solutions et de participants. La thèse prolonge Simon en déplaçant l'attention du décideur vers le processus. Trois constats la fondent. Les objectifs d'une organisation sont multiples, ambigus et souvent découverts après coup, de sorte qu'il est illusoire de poser une fonction d'objectif unique à maximiser. L'attention des participants est une ressource rare : un problème n'est traité que lorsqu'il parvient à capter cette attention, et non lorsqu'il est le plus urgent. Les solutions, enfin, préexistent parfois aux problèmes et cherchent une occasion de s'appliquer. La décision apparaît alors moins comme la résolution d'un problème que comme la rencontre, à un moment donné, de participants disponibles, de problèmes saillants et de solutions en circulation.",
  'po': "Dans le chapitre, cette analyse constitue le prolongement le plus abouti de la rationalité limitée et complète l'analyse stratégique de Crozier : si celle-ci montre que les acteurs ont des intérêts, March montre que les processus eux-mêmes sont désordonnés. Les documents d'Écosphère le citent aux côtés de Simon et de Merton dans la filiation que Crozier a contribué à diffuser en France.",
  'co': "James March montre que la décision en organisation résulte de la rencontre contingente de problèmes, de solutions et de participants : les objectifs y sont ambigus, l'attention est une ressource rare, et des solutions préexistantes cherchent souvent un problème auquel s'appliquer.",
 },
 'Société salariale et désaffiliation': {
  'af': "Castel soutient que la société salariale avait fait de l'emploi un support d'intégration en associant au salaire un statut et des droits, et que sa fragilisation enclenche un processus de désaffiliation qui dépasse de loin la perte de revenu. La thèse repose sur une reconstitution historique : la condition salariale, misérable et précaire au XIXᵉ siècle, devient au XXᵉ un statut protégé par le droit du travail, la protection sociale et les conventions collectives. L'emploi cesse alors d'être une simple rémunération pour devenir un titre donnant accès à des droits, à une identité et à une place reconnue. La montée du chômage et de la précarité défait cet assemblage. La désaffiliation combine trois pertes simultanées : les protections attachées au statut, les relations que le travail procurait, et l'identité qu'il conférait. Castel distingue à cette fin trois zones — intégration, vulnérabilité, désaffiliation — qui permettent de penser des trajectoires plutôt que des catégories figées.",
  'po': "Dans le chapitre, cette analyse actualise la thèse durkheimienne de l'intégration par le travail en montrant ce qui advient lorsque ses conditions se défont. Elle fournit le cadre conceptuel de l'étude de la précarisation et relie la sociologie du travail aux transformations de l'emploi étudiées en économie.",
  'co': "Robert Castel montre que la société salariale avait associé au salaire un statut et des droits : sa fragilisation enclenche une désaffiliation combinant perte des protections, des relations et de l'identité, selon un continuum allant de l'intégration à la vulnérabilité puis à la désaffiliation.",
 },
 'Enquête en immersion sur le travail précaire': {
  'af': "L'enquête de Florence Aubenas établit que l'emploi précaire ne se réduit pas à un bas salaire mais désorganise la vie entière, par un cumul de contraintes qui se renforcent mutuellement. La thèse procède de l'immersion, méthode qui révèle ce que les statistiques agrègent. Les horaires morcelés rendent impossible le cumul d'un second emploi tout en occupant la journée entière. La dispersion des lieux de travail transforme le transport en coût majeur, en argent comme en temps non rémunéré. L'instabilité des équipes empêche la formation de collectifs et donc toute solidarité professionnelle. L'incertitude sur le mois suivant interdit enfin tout engagement — logement, crédit, formation — c'est-à-dire toute projection dans l'avenir. La précarité apparaît ainsi comme un cumul de contraintes qui s'alimentent, et non comme un simple niveau de revenu inférieur.",
  'po': "Dans le chapitre, cette enquête fournit la matière empirique des analyses de Castel et montre concrètement les trois pertes de la désaffiliation. Elle illustre également une méthode des sciences sociales, l'enquête par immersion, dont la valeur tient à ce qu'elle donne accès à ce que les catégories statistiques ne saisissent pas.",
  'co': "L'enquête en immersion de Florence Aubenas montre que la précarité cumule des contraintes qui se renforcent : horaires morcelés, transports coûteux en temps non rémunéré, instabilité des collectifs et impossibilité de se projeter, bien au-delà du seul niveau de salaire.",
 },
 'Expérience de la condition ouvrière': {
  'af': "Simone Weil soutient que la condition ouvrière ne peut pas être comprise de l'extérieur, et son expérience du travail en usine en 1934 lui permet d'en décrire les effets sur la personne. La thèse va au-delà du constat de pénibilité. Elle décrit la cadence imposée qui interdit la réflexion, l'épuisement qui dissout progressivement la volonté et jusqu'à la capacité de révolte, la soumission à des ordres dont le sens n'est jamais donné, et la peur permanente du renvoi qui interdit toute contestation. Son apport propre est de montrer que le travail dégradé n'opprime pas seulement matériellement : il atteint la faculté de penser et le sentiment d'exister comme personne. Cette analyse explique un fait que les théories de la mobilisation peinent à rendre : dans ces conditions, la révolte est rare plutôt que fréquente, précisément parce que l'épuisement ôte les ressources qu'elle exigerait.",
  'po': "Dans le chapitre, ce témoignage fournit la dimension vécue que les analyses structurelles de Marx et de Taylor laissent de côté, et complète l'approche sociologique par une approche de l'expérience. Il montre que l'organisation du travail produit des effets sur les personnes qu'aucun indicateur de productivité ne mesure.",
  'co': "L'expérience du travail en usine conduite par Simone Weil en 1934 montre que le travail dégradé n'opprime pas seulement matériellement : la cadence et l'épuisement atteignent la faculté de penser elle-même, ce qui explique que la révolte y soit rare plutôt que fréquente.",
 },
 'Institutionnalisation des sciences sociales allemandes': {
  'af': "La participation de Sombart, aux côtés de Weber, à la création en 1903 d'une revue majeure de sciences sociales allemandes illustre le processus par lequel une discipline se constitue. La thèse sous-jacente est que l'existence d'une science ne tient pas seulement à la qualité des idées mais à des supports matériels : une revue qui fixe des critères de publication et arbitre les controverses, des associations savantes qui organisent le débat, des chaires qui assurent la transmission. L'enjeu de cette période est méthodologique autant qu'institutionnel : il s'agit d'établir la possibilité d'une science du social distincte des sciences de la nature, question qui structure alors les débats allemands comme français. Les documents d'Écosphère mentionnent cette collaboration sans développer davantage l'œuvre propre de Sombart : il convient donc de l'utiliser comme repère de contexte et non comme référence théorique autonome.",
  'po': "Dans le chapitre, cette mention situe l'émergence de la sociologie dans son contexte institutionnel et rappelle que les sciences sociales se sont constituées à un moment précis, contre des oppositions. Elle fait pendant à la fondation de L'Année sociologique par Durkheim en 1896, qui relève du même mouvement en France.",
  'co': "La création en 1903, par Sombart et Weber, d'une revue majeure de sciences sociales allemandes illustre le processus d'institutionnalisation de la discipline, parallèle à la fondation de L'Année sociologique par Durkheim en 1896.",
 },
}

SPLIT[10] = [
 ('Émile Durkheim', "Anomie, égoïsme et pathologies du lien social", {
  'affirme': "Durkheim soutient que la division du travail ne produit de la solidarité que si elle est régulée, et il nomme pathologies les situations où cette condition n'est pas remplie. Deux d'entre elles sont décisives pour l'analyse économique. L'anomie désigne un défaut de régulation : les règles qui encadraient les aspirations et les échanges ont disparu ou ne sont plus intériorisées, de sorte que les désirs, par nature illimités, ne rencontrent plus de borne. Durkheim souligne que cette absence de limite n'est pas une libération mais une souffrance, car un désir sans terme est un désir nécessairement déçu. L'égoïsme désigne un défaut d'intégration : l'individu n'est plus rattaché à un groupe qui donne sens à son existence. Ces deux pathologies ne relèvent pas de la psychologie individuelle mais de l'état du lien social, ce qui illustre la méthode durkheimienne consistant à traiter les faits sociaux comme des choses.",
  'mecanisme': "Le raisonnement établit une causalité sociale là où l'on attendrait une explication individuelle. Premièrement, Durkheim pose que les aspirations humaines ne connaissent pas de limite interne : seule une régulation extérieure, sociale, peut leur en assigner une. Deuxièmement, les périodes de changement brutal — crise économique mais aussi prospérité soudaine — défont cette régulation, car les repères antérieurs sur ce qu'il est légitime d'espérer deviennent caducs. Troisièmement, l'individu dont les aspirations excèdent indéfiniment ses possibilités éprouve une insatisfaction permanente, qui se traduit statistiquement par une hausse du taux de suicide. Quatrièmement, le raisonnement vaut symétriquement pour l'intégration : un individu détaché de tout groupe perd les raisons d'agir que le collectif fournissait. Le point méthodologique essentiel est que ces variations s'expliquent par des caractéristiques des sociétés et non des individus.",
  'exemple': "Durkheim relève que le taux de suicide s'élève non seulement lors des crises économiques mais aussi lors des phases d'enrichissement rapide : ce n'est donc pas la pauvreté qui agit, mais la rupture des repères qui assignaient une limite aux aspirations.",
  'diss': "Référence majeure sur « le travail intègre-t-il encore ? », « quelles conséquences sociales des transformations économiques ? », « la cohésion sociale ». Place : deuxième partie, pour montrer que les transformations économiques agissent sur le lien social par la régulation et l'intégration, et non seulement par le revenu.",
  'portee': "Dans le chapitre, cette analyse fournit les deux concepts qui permettent d'évaluer les transformations du travail : une organisation peut détruire la régulation ou l'intégration, et dans les deux cas produire des effets mesurables. Elle fonde la méthode holiste du chapitre et donne à Castel ses instruments d'analyse de la désaffiliation.",
  'copie': "Durkheim distingue deux pathologies du lien social : l'anomie, défaut de régulation qui laisse les aspirations sans limite et donc nécessairement déçues, et l'égoïsme, défaut d'intégration qui détache l'individu de tout groupe — deux états de la société et non de l'individu.",
  'ouvrage': "De la division du travail social (1893) ; Le Suicide (1897)",
  'notions': ['anomie', 'égoïsme', 'régulation', 'intégration', 'fait social'],
  'liens': [('Robert Castel', 'prolonge', "La désaffiliation décrit la forme contemporaine du double défaut de régulation et d'intégration."),
            ('Carl Menger', 'opposition', "Le holisme durkheimien s'oppose frontalement à l'individualisme méthodologique autrichien."),
            ('Florence Aubenas', 'complement', "L'enquête donne à voir les effets concrets de la perte des repères et des collectifs.")],
 }),
 ('Michel Crozier', "Le cercle vicieux bureaucratique", {
  'affirme': "Crozier soutient que l'organisation bureaucratique est incapable de se réformer par les moyens dont elle dispose, parce que chaque tentative de correction engendre les dysfonctionnements qu'elle prétend supprimer. La thèse décrit un mécanisme autoentretenu. Face à un dysfonctionnement, la direction réagit par ce qu'elle sait faire : édicter une règle supplémentaire, plus précise et impersonnelle. Cette règle supprime effectivement la marge de manœuvre visée, mais elle produit trois effets pervers. Elle crée de nouvelles zones d'incertitude, donc de nouveaux foyers de pouvoir informel. Elle renforce l'impersonnalité des rapports et l'isolement des strates hiérarchiques, qui communiquent de moins en moins. Elle rend l'organisation plus rigide, donc moins capable de traiter les cas imprévus, ce qui multiplie les dysfonctionnements. La direction édicte alors de nouvelles règles, et le cycle recommence : la bureaucratie ne corrige pas ses défauts, elle les approfondit.",
  'mecanisme': "Le cercle comporte quatre moments enchaînés. Premièrement, l'organisation développe des règles impersonnelles pour limiter l'arbitraire, ce qui est conforme au modèle wébérien. Deuxièmement, ces règles réduisent les relations directes entre niveaux hiérarchiques, chacun se retranchant derrière la procédure : les strates s'isolent et l'information circule mal. Troisièmement, les décisions remontent alors à un niveau éloigné du terrain, où elles sont prises sans la connaissance des situations concrètes, ce qui produit des décisions inadaptées. Quatrièmement, les acteurs de terrain, confrontés à des règles inapplicables, développent des arrangements informels qui leur procurent du pouvoir et qu'ils protègent. La direction, constatant ces écarts, édicte de nouvelles règles — et l'on repart au premier moment. Le système est donc stable dans son dysfonctionnement, ce qui explique sa remarquable résistance au changement.",
  'exemple': "Une direction qui, pour mettre fin aux arrangements informels des équipes de terrain, édicte une procédure détaillée obtient le plus souvent que ces équipes développent de nouveaux arrangements pour rendre la procédure applicable — déplaçant le problème sans le résoudre.",
  'diss': "Référence centrale sur « peut-on réformer par la règle ? », « l'organisation bureaucratique est-elle efficace ? », « pourquoi les réformes échouent-elles ? ». Place : deuxième ou troisième partie, pour montrer que l'échec des réformes n'est pas un défaut d'exécution mais une propriété du système réformé.",
  'portee': "Dans le chapitre, cette analyse achève la critique du modèle wébérien en montrant que la bureaucratie n'est pas seulement imparfaite mais structurellement incapable de s'amender. Elle justifie l'approche par les acteurs que Friedberg systématisera et les métarègles que Morel proposera, lesquelles portent sur la manière de décider et non sur le contenu des règles.",
  'copie': "Michel Crozier décrit un cercle vicieux bureaucratique : chaque règle édictée pour corriger un dysfonctionnement isole davantage les strates hiérarchiques, éloigne la décision du terrain et crée de nouvelles zones d'incertitude, ce qui engendre les dysfonctionnements qu'une nouvelle règle viendra prétendument corriger.",
  'ouvrage': "Le Phénomène bureaucratique (1963)",
  'notions': ['cercle vicieux bureaucratique', 'règle impersonnelle', 'isolement des strates', 'résistance au changement'],
  'liens': [('Max Weber', 'opposition', "Le type idéal de la bureaucratie rationnelle est précisément ce que l'enquête de terrain contredit."),
            ('Erhard Friedberg', 'complement', "L'analyse stratégique systématise la méthode qui permet de comprendre ce cercle."),
            ('Christian Morel', 'prolonge', "Les métarègles répondent à ce blocage en portant sur la procédure de décision plutôt que sur son contenu.")],
 }),
]
